<template>
  <div class="container q-pt-md">
    <div class="full-width">
      <DocBitsTable
        :rows="licenseData"
        :columns="columns"
        :loading="false"
        row-key="Name"
        table-id="api_licenses_table"
        :features="{
          sorting: false,
          filtering: false,
          selection: false,
          bulkActions: false,
          rowActions: false,
          resizable: false,
          pagination: false,
          columnReorder: false,
          columnSettings: false,
          stickyFirstColumn: false,
          stickyLastColumn: false,
        }"
        no-data-label="no_record_found"
        table-class="api-licenses-table-height"
        flat-style
      >
        <!-- Name column -->
        <template #body-cell-Name="{ row }">
          {{ row.Name }}
        </template>

        <!-- License column -->
        <template #body-cell-License="{ row }">
          {{ row.License }}
        </template>

        <!-- Version column -->
        <template #body-cell-Version="{ row }">
          {{ row.Version }}
        </template>
      </DocBitsTable>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { DocBitsTable } from 'src/components/Table';
import type { UnifiedTableColumn } from 'src/components/Table';
import { API_LICENSES } from 'src/pages/Settings/Licenses/licenses';

interface LicenseItem {
  Name: string;
  License: string;
  Version: string;
}

export default defineComponent({
  name: 'ApiLicenses',
  components: {
    DocBitsTable,
  },
  computed: {
    columns(): UnifiedTableColumn[] {
      return [
        {
          name: 'Name',
          label: this.$t('name'),
          field: 'Name',
          sortable: false,
          align: 'left',
        },
        {
          name: 'License',
          label: this.$t('license'),
          field: 'License',
          sortable: false,
          align: 'left',
        },
        {
          name: 'Version',
          label: this.$t('version'),
          field: 'Version',
          sortable: false,
          align: 'left',
          style: 'width: 100px',
        },
      ];
    },
    licenseData(): LicenseItem[] {
      return API_LICENSES[0]?.licenses || [];
    },
  },
});
</script>

<style lang="scss" scoped>
:deep(.api-licenses-table-height) {
  height: calc(100vh - 130px) !important;
}
